TAX = 0.2


def subtotal(items):
    return sum(i["price"] * i["qty"] for i in items)


def tax(items):
    return round(subtotal(items) * TAX, 2)


def total(items, coupon=None):
    t = subtotal(items) + tax(items)
    return t - coupon["off"] if coupon else t

from billing import subtotal, tax, total


def receipt(items, coupon=None):
    return {"subtotal": subtotal(items), "tax": tax(items), "total": total(items, coupon)}
